//! Idiomatic Rust translation of the PCSX2 IOP module catalogue and the
//! `SaveState` / `StateWrapper` save-state subsystem.
//!
//! This module contains:
//!
//! * [`IOP_MODULES`] - the catalogue of all IOP module function exports
//!   generated by `IopModuleNames.cpp`.
//! * [`SaveState`] - the top-level file-oriented state container that owns
//!   the underlying byte buffer, the read/write cursor, and the section
//!   stack. It supports `open` / `save` / `load` plus typed
//!   `read_*` / `write_*` primitives.
//! * [`StateWrapper`] - a RAII section guard returned by
//!   [`SaveState::begin_section`]. It exposes the same typed read/write
//!   primitives, marks the section, and automatically calls
//!   [`SaveState::end_section`] when dropped.
//!
//! Only the `std` crate is used.

use std::fs::File;
use std::io::{self, Read, Write};
use std::marker::PhantomData;
use std::path::{Path, PathBuf};

// ---------------------------------------------------------------------------
//  Versioning
// ---------------------------------------------------------------------------

/// The full PCSX2 save-state version constant.
///
/// Mirrors `g_SaveVersion` from `SaveState.h`. The high 16 bits classify the
/// PCSX2 build type, the low 16 bits are the rolling savestate version.
pub const SAVE_VERSION: u32 = (0x9A59u32 << 16) | 0x0000;

/// `STATE_PCSX2_VERSION_SIZE` from `SaveState.cpp`.
pub const STATE_PCSX2_VERSION_SIZE: usize = 32;

/// `EntryFilename_StateVersion` from `SaveState.cpp`.
pub const ENTRY_FILENAME_STATE_VERSION: &str = "PCSX2 Savestate Version.id";

/// `EntryFilename_Screenshot` from `SaveState.cpp`.
pub const ENTRY_FILENAME_SCREENSHOT: &str = "Screenshot.png";

/// `EntryFilename_InternalStructures` from `SaveState.cpp`.
pub const ENTRY_FILENAME_INTERNAL_STRUCTURES: &str = "PCSX2 Internal Structures.dat";

